use std::usize;

fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    assert!(n >= 2);

    // Because for any distinct i, j: nums[i] + nums[j] < 256,
    // any number that participates in a valid pair must be < 256 as well.
    // This allows a simple value->first_index table over 0..255.
    let mut first_pos: [Option<usize>; 256] = [None; 256];

    // Scan left-to-right; for each i, try to pair nums[i] with an earlier j.
    // Returning at the first hit gives the lexicographically smallest (p, q).
    for i in 0..n {
        let x = nums[i] as usize;
        assert!(x < 256);

        if target < nums[i] {
            // complement would underflow, so no earlier value can match
        } else {
            let need = (target - nums[i]) as usize;
            if need < 256 {
                if let Some(j) = first_pos[need] {
                    // j < i by construction, and since j is the earliest index
                    // with that value, this is the lexicographically smallest pair.
                    return (j, i);
                }
            }
        }

        // Record earliest occurrence of nums[i] for future indices.
        if first_pos[x].is_none() {
            first_pos[x] = Some(i);
        }
    }

    // Problem statement guarantees a solution exists.
    unreachable!();
}